import{_ as a,a0 as r,w as l,s as h,ao as i,I as p,x as e,a1 as o,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7","title":"如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器","tag":"201607","desc":""},"relativePath":"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7.md","filePath":"[post].md"}'),s={name:"201607/20160219 How to Setup Lighttpd Web server on Ubuntu 15.04 or CentOS 7.md"};function g(u,t,c,b,m,f){const n=r("Link");return l(),h("div",null,[t[19]||(t[19]=i(`<h1 id="如何在-ubuntu-15-04-centos-7-中安裝-lighttpd-web-服務器" tabindex="-1">如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器 <a class="header-anchor" href="#如何在-ubuntu-15-04-centos-7-中安裝-lighttpd-web-服務器" aria-label="Permalink to “如何在 Ubuntu 15.04/CentOS 7 中安裝 Lighttpd Web 服務器”">​</a></h1><p>Lighttpd 是一款開源 Web 服務器軟件。Lighttpd 安全快速，符合行業標準，適配性強並且針對高配置環境進行了優化。相對於其它的 Web 服務器而言，Lighttpd 佔用內存更少；因其對 CPU 佔用小和對處理速度的優化而在效率和速度方面從眾多 Web 服務器中脱穎而出。而 Lighttpd 諸如 FastCGI、CGI、認證、輸出壓縮、URL 重寫等高級功能更是那些面臨性能壓力的服務器的福音。</p><p>以下便是我們在運行 Ubuntu 15.04 或 CentOS 7 Linux 發行版的機器上安裝 Lighttpd Web 服務器的簡要流程。</p><h3 id="安裝lighttpd" tabindex="-1">安裝Lighttpd <a class="header-anchor" href="#安裝lighttpd" aria-label="Permalink to “安裝Lighttpd”">​</a></h3><h4 id="使用包管理器安裝" tabindex="-1">使用包管理器安裝 <a class="header-anchor" href="#使用包管理器安裝" aria-label="Permalink to “使用包管理器安裝”">​</a></h4><p>這裏我們通過使用包管理器這種最簡單的方法來安裝 Lighttpd。只需以 sudo 模式在終端或控制台中輸入下面的指令即可。</p><p><strong>CentOS 7</strong></p><p>由於 CentOS 7.0 官方倉庫中並沒有提供 Lighttpd，所以我們需要在系統中安裝額外的軟件源 epel 倉庫。使用下面的 yum 指令來安裝 epel。</p><pre><code># yum install epel-release
</code></pre><p>然後，我們需要更新系統及為 Lighttpd 的安裝做前置準備。</p><pre><code># yum update
# yum install lighttpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/install-lighttpd-centos.png" alt="Install Lighttpd Centos"></p><p><strong>Ubuntu 15.04</strong></p><p>Ubuntu 15.04 官方倉庫中包含了 Lighttpd，所以只需更新本地倉庫索引並使用 apt-get 指令即可安裝 Lighttpd。</p><pre><code># apt-get update
# apt-get install lighttpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/install-lighttpd-ubuntu.png" alt="Install lighttpd ubuntu"></p><h4 id="從源代碼安裝-lighttpd" tabindex="-1">從源代碼安裝 Lighttpd <a class="header-anchor" href="#從源代碼安裝-lighttpd" aria-label="Permalink to “從源代碼安裝 Lighttpd”">​</a></h4><p>如果想從 Lighttpd 源碼安裝最新版本（例如 1.4.39），我們需要在本地編譯源碼並進行安裝。首先我們要安裝編譯源碼所需的依賴包。</p><pre><code># cd /tmp/
# wget http://download.lighttpd.net/lighttpd/releases-1.4.x/lighttpd-1.4.39.tar.gz
</code></pre><p>下載完成後，執行下面的指令解壓縮。</p><pre><code># tar -zxvf lighttpd-1.4.39.tar.gz
</code></pre><p>然後使用下面的指令進行編譯。</p><pre><code># cd lighttpd-1.4.39
# ./configure
# make
</code></pre><p><strong>注：</strong>在這份教程中，我們安裝的是默認配置的 Lighttpd。其他拓展功能，如對 SSL 的支持，mod_rewrite，mod_redirect 等，需自行配置。</p><p>當編譯完成後，我們就可以把它安裝到系統中了。</p><pre><code># make install
</code></pre><h3 id="設置-lighttpd" tabindex="-1">設置 Lighttpd <a class="header-anchor" href="#設置-lighttpd" aria-label="Permalink to “設置 Lighttpd”">​</a></h3><p>如果有更高的需求，我們可以通過修改默認設置文件，如<code>/etc/lighttpd/lighttpd.conf</code>，來對 Lighttpd 進行進一步設置。 而在這份教程中我們將使用默認設置，不對設置文件進行修改。如果你曾做過修改並想檢查設置文件是否出錯，可以執行下面的指令。</p><pre><code># lighttpd -t -f /etc/lighttpd/lighttpd.conf
</code></pre><h4 id="使用-centos-7" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><p>在 CentOS 7 中，我們需創建一個在 Lighttpd 默認配置文件中設置的 webroot 文件夾，例如<code>/src/www/htdocs</code>。</p><pre><code># mkdir -p /srv/www/htdocs/
</code></pre><p>而後將默認歡迎頁面從<code>/var/www/lighttpd</code>複製至剛剛新建的目錄中：</p><pre><code># cp -r /var/www/lighttpd/* /srv/www/htdocs/
</code></pre><h3 id="開啓服務" tabindex="-1">開啓服務 <a class="header-anchor" href="#開啓服務" aria-label="Permalink to “開啓服務”">​</a></h3><p>現在，通過執行 systemctl 指令來重啓 Web 服務。</p><pre><code># systemctl start lighttpd
</code></pre><p>然後我們將它設置為伴隨系統啓動自動運行。</p><pre><code># systemctl enable lighttpd
</code></pre><h3 id="設置防火牆" tabindex="-1">設置防火牆 <a class="header-anchor" href="#設置防火牆" aria-label="Permalink to “設置防火牆”">​</a></h3><p>如要讓我們運行在 Lighttpd 上的網頁或網站能在 Internet 或同一個網絡內被訪問，我們需要在防火牆程序中設置打開 80 端口。由於 CentOS 7 和 Ubuntu15.04 都附帶 Systemd 作為默認初始化系統，所以我們默認用的都是 firewalld。如果要打開 80 端口或 http 服務，我們只需執行下面的命令：</p><pre><code># firewall-cmd --permanent --add-service=http
success
# firewall-cmd --reload
success
</code></pre><h3 id="連接至-web-服務器" tabindex="-1">連接至 Web 服務器 <a class="header-anchor" href="#連接至-web-服務器" aria-label="Permalink to “連接至 Web 服務器”">​</a></h3>`,43)),p("p",null,[t[1]||(t[1]=e("在將 80 端口設置為默認端口後，我們就可以直接訪問 Lighttpd 的默認歡迎頁了。我們需要根據運行 Lighttpd 的設備來設置瀏覽器的 IP 地址和域名。在本教程中，我們令瀏覽器訪問 ",-1)),o(n,{href:"http://lighttpd.linoxide.com/"},{default:d(()=>[...t[0]||(t[0]=[e("http://lighttpd.linoxide.com/",-1)])]),_:1}),t[2]||(t[2]=e(" ，同時將該子域名指向上述 IP 地址。如此一來，我們就可以在瀏覽器中看到如下的歡迎頁面了。",-1))]),t[20]||(t[20]=i(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2016/02/lighttpd-welcome-page.png" alt="Lighttpd Welcome Page"></p><p>此外，我們可以將網站的文件添加到 webroot 目錄下，並刪除 Lighttpd 的默認索引文件，使我們的靜態網站可以在互聯網上訪問。</p><p>如果想在 Lighttpd Web 服務器中運行 PHP 應用，請參考下面的步驟：</p><h3 id="安裝-php5-模組" tabindex="-1">安裝 PHP5 模組 <a class="header-anchor" href="#安裝-php5-模組" aria-label="Permalink to “安裝 PHP5 模組”">​</a></h3><p>在 Lighttpd 成功安裝後，我們需要安裝 PHP 及相關模組，以在 Lighttpd 中運行 PHP5 腳本。</p><h4 id="使用-ubuntu-15-04" tabindex="-1">使用 Ubuntu 15.04 <a class="header-anchor" href="#使用-ubuntu-15-04" aria-label="Permalink to “使用 Ubuntu 15.04”">​</a></h4><pre><code># apt-get install php5 php5-cgi php5-fpm php5-mysql php5-curl php5-gd php5-intl php5-imagick php5-mcrypt php5-memcache php-pear
</code></pre><h4 id="使用-centos-7-1" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7-1" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><pre><code># yum install php php-cgi php-fpm php-mysql php-curl php-gd php-intl php-pecl-imagick php-mcrypt php-memcache php-pear lighttpd-fastcgi
</code></pre><h3 id="設置-lighttpd-的-php-服務" tabindex="-1">設置 Lighttpd 的 PHP 服務 <a class="header-anchor" href="#設置-lighttpd-的-php-服務" aria-label="Permalink to “設置 Lighttpd 的 PHP 服務”">​</a></h3><p>如要讓 PHP 與 Lighttpd 協同工作，我們只要根據所使用的發行版執行如下對應的指令即可。</p><h4 id="使用-centos-7-2" tabindex="-1">使用 CentOS 7 <a class="header-anchor" href="#使用-centos-7-2" aria-label="Permalink to “使用 CentOS 7”">​</a></h4><p>首先要做的便是使用文件編輯器編輯 php 設置文件（例如<code>/etc/php.ini</code>）並取消掉對<strong>cgi.fix_pathinfo=1</strong>這一行的註釋。</p><pre><code># nano /etc/php.ini
</code></pre><p>完成上面的步驟之後，我們需要把 PHP-FPM 進程的所有權從 Apache 轉移至 Lighttpd。要完成這些，首先用文件編輯器打開<code>/etc/php-fpm.d/www.conf</code>文件。</p><pre><code># nano /etc/php-fpm.d/www.conf
</code></pre><p>然後在文件中增加下面的語句：</p><pre><code>user = lighttpd
group = lighttpd
</code></pre><p>做完這些，我們保存並退出文本編輯器。然後從<code>/etc/lighttpd/modules.conf</code>設置文件中添加 FastCGI 模組。</p><pre><code># nano /etc/lighttpd/modules.conf
</code></pre><p>然後，去掉下面語句前面的<code>#</code>來取消對它的註釋。</p><pre><code>include &quot;conf.d/fastcgi.conf&quot;
</code></pre><p>最後我們還需在文本編輯器設置 FastCGI 的設置文件。</p><pre><code># nano /etc/lighttpd/conf.d/fastcgi.conf
</code></pre><p>在文件尾部添加以下代碼：</p><pre><code>fastcgi.server += ( &quot;.php&quot; =&gt;
((
&quot;host&quot; =&gt; &quot;127.0.0.1&quot;,
&quot;port&quot; =&gt; &quot;9000&quot;,
&quot;broken-scriptfilename&quot; =&gt; &quot;enable&quot;
))
)
</code></pre><p>在編輯完成後保存並退出文本編輯器即可。</p><h4 id="使用-ubuntu-15-04-1" tabindex="-1">使用 Ubuntu 15.04 <a class="header-anchor" href="#使用-ubuntu-15-04-1" aria-label="Permalink to “使用 Ubuntu 15.04”">​</a></h4><p>如需啓用 Lighttpd 的 FastCGI，只需執行下列代碼：</p><pre><code># lighttpd-enable-mod fastcgi

Enabling fastcgi: ok
Run /etc/init.d/lighttpd force-reload to enable changes

# lighttpd-enable-mod fastcgi-php

Enabling fastcgi-php: ok
Run \`/etc/init.d/lighttpd\` force-reload to enable changes
</code></pre><p>然後，執行下列命令來重啓 Lighttpd。</p><pre><code># systemctl force-reload lighttpd
</code></pre><h3 id="檢測-php-工作狀態" tabindex="-1">檢測 PHP 工作狀態 <a class="header-anchor" href="#檢測-php-工作狀態" aria-label="Permalink to “檢測 PHP 工作狀態”">​</a></h3><p>如需檢測 PHP 是否按預期工作，我們需在 Lighttpd 的 webroot 目錄下新建一個 php 文件。本教程中，在 Ubuntu 下 /var/www/html 目錄，CentOS 下 /src/www/htdocs 目錄下使用文本編輯器創建並打開 info.php。</p><p><strong>使用 CentOS 7</strong></p><pre><code># nano  /var/www/info.php
</code></pre><p><strong>使用 Ubuntu 15.04</strong></p><pre><code># nano /srv/www/htdocs/info.php
</code></pre><p>然後只需將下面的語句添加到文件裏即可。</p><pre><code>&lt;?php phpinfo(); ?&gt;
</code></pre><p>在編輯完成後保存並推出文本編輯器即可。</p>`,41)),p("p",null,[t[4]||(t[4]=e("現在，我們需根據路徑 ",-1)),o(n,{href:"http://lighttpd.linoxide.com/info.php"},{default:d(()=>[...t[3]||(t[3]=[e("http://lighttpd.linoxide.com/info.php",-1)])]),_:1}),t[5]||(t[5]=e(" 下的 info.php 文件的 IP 地址或域名，來讓我們的網頁瀏覽器指向系統上運行的 Lighttpd。如果一切都按照以上説明進行，我們將看到如下圖所示的 PHP 頁面信息。",-1))]),t[21]||(t[21]=p("p",null,[p("img",{src:"http://blog.linoxide.com/wp-content/uploads/2016/02/phpinfo-lighttpd.png",alt:"phpinfo lighttpd"})],-1)),t[22]||(t[22]=p("h3",{id:"總結",tabindex:"-1"},[e("總結 "),p("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[23]||(t[23]=p("p",null,"至此，我們已經在 CentOS 7 和 Ubuntu 15.04 Linux 發行版上成功安裝了輕巧快捷並且安全的 Lighttpd Web 服務器。現在，我們已經可以上傳網站文件到網站根目錄、配置虛擬主機、啓用 SSL、連接資料庫，在我們的 Lighttpd Web 服務器上運行 Web 應用等功能了。 如果你有任何疑問，建議或反饋請在下面的評論區中寫下來以讓我們更好的改良 Lighttpd。謝謝！",-1)),t[24]||(t[24]=p("hr",null,null,-1)),p("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"http://linoxide.com/linux-how-to/setup-lighttpd-web-server-ubuntu-15-04-centos-7/"},{default:d(()=>[...t[6]||(t[6]=[e("http://linoxide.com/linux-how-to/setup-lighttpd-web-server-ubuntu-15-04-centos-7/",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=e("作者：",-1)),o(n,{href:"http://linoxide.com/author/arunp/"},{default:d(()=>[...t[8]||(t[8]=[e("Arun Pyasi",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(n,{href:"https://github.com/HaohongWANG"},{default:d(()=>[...t[9]||(t[9]=[e("HaohongWANG",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:d(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:d(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const C=a(s,[["render",g]]);export{P as __pageData,C as default};
